# sneaker_manager/app/models.pyfrom sqlalchemy import Column, Integer, String, Float, ForeignKey, Date, DateTime, Textfrom sqlalchemy.ext.declarative import declarative_basefrom sqlalchemy.orm import relationshipfrom sqlalchemy.ext.hybrid import hybrid_propertyfrom pypinyin import lazy_pinyinfrom datetime import datetimeBase = declarative_base()class Sneaker(Base):    __tablename__ = 'sneakers'    id = Column(Integer, primary_key=True)    name = Column(String(100), nullable=False)    brand = Column(String(50))    series = Column(String(50))    purchase_date = Column(String(10))    purchase_price = Column(Float)    image_path = Column(String(200))    size = Column(Float)    color = Column(String(100), default='')    status = Column(String, default="使用中")  #球鞋使用状态，在新增时默认为使用中    # —— 新增字段 —— #    item_number = Column(String(50), default='')  # 货号    condition = Column(String(10), default='全新')  # 球鞋新旧    has_box = Column(String(2), default='是')  # 是否有鞋盒    actual = Column(String(2), default='是')  # 是否实战鞋    shoe_type = Column(String(20), default='篮球鞋')  # 球鞋类型    # 新增字段存储拼音首字母    name_pinyin = Column(String(200), index=True)  # 添加索引提升搜索性能    ratings = relationship("Rating", back_populates="sneaker", order_by="Rating.created_at",                           cascade="all, delete-orphan")    usage_records = relationship("UsageRecord",back_populates="sneaker", cascade="all, delete-orphan",                                 passive_deletes=True)    def __init__(self, **kwargs: object) -> object:        super().__init__(**kwargs)        # 自动生成拼音首字母        self.name_pinyin = self._generate_pinyin()    def _generate_pinyin(self):        """生成名称拼音首字母"""        try:            return ''.join([s[0] for s in lazy_pinyin(self.name)])        except:            return ""class UsageRecord(Base):    __tablename__ = 'usage_records'    id = Column(Integer, primary_key=True)    sneaker_id = Column(Integer, ForeignKey("sneakers.id",ondelete="CASCADE"), nullable=False)    date = Column(Date)  # 建议直接用 Date 类型，便于查询    location = Column(String(100), nullable=True)    activity = Column(String(50), nullable=False)    duration = Column(Integer, nullable=False)  # 单位：分钟    notes = Column(String(2000), nullable=True)  # 感受记录，最多2000字    image_paths = Column(Text, default="",nullable=True)  # 新增：存多张图片路径，用 ';' 分隔    sneaker = relationship("Sneaker", back_populates="usage_records")class Rating(Base):    __tablename__ = 'rating_records'    id = Column(Integer, primary_key=True)    sneaker_id = Column(Integer, ForeignKey("sneakers.id"), nullable=False)    cushion = Column(Integer)  #缓震    traction = Column(Integer)  #抓地    torsion = Column(Integer)  #抗扭    durability = Column(Integer)  #耐磨    # 多选 & 单选字段都存字符串    width = Column(String(50))  # 鞋楦，多选，逗号分隔    inner_length = Column(String(10))  # 内长，单选    insole = Column(String(200))  # 鞋垫，多选    depth = Column(String(20))  # 鞋仓深度，单选    # 新增的 4 个 1–10 滑条分数    wrap = Column(Integer)  # 包裹    anti_roll = Column(Integer)  # 防侧翻    weight = Column(Integer)  # 重量    comfort = Column(Integer)  # 舒适性    created_at = Column(DateTime, default=datetime.utcnow)    sneaker = relationship("Sneaker", back_populates="ratings")